removeDecorationType(key) {
        const provider = this.t.get(key);
        if (provider) {
            provider.refCount--;
            if (provider.refCount <= 0) {
                this.t.delete(key);
                provider.dispose();
                this.listCodeEditors().forEach((ed) => ed.removeDecorationsByType(key));
            }
        }
    }
